python3 - <<'PY'
import json

# Load existing flow (has trigger node + trigger definition)
flow = json.load(open('VendorInvoiceProcessing.flow'))

# Load definitions from registry
script_def = json.load(open('/tmp/script_registry.json'))['Data']['Node']
end_def    = json.load(open('/tmp/end_registry.json'))['Data']['Node']
mock_def   = json.load(open('/tmp/mock_registry.json'))['Data']['Node']

# ── Nodes ──────────────────────────────────────────────────────────────────────
# Node IDs:
#   newInvoiceInSharepoint1  – SharePoint trigger (already exists)
#   extractInvoiceFieldsMock – IxP mock (pending model deployment)
#   formatResults            – script node: extract named fields
#   errorHandler             – script node: log/surface errors
#   doneSuccess              – end node (success path)
#   doneError                – end node (error path)

EXTRACT_SCRIPT = r"""
const fields = ($vars.extractInvoiceFieldsMock.output &&
                $vars.extractInvoiceFieldsMock.output.ExtractionResult &&
                $vars.extractInvoiceFieldsMock.output.ExtractionResult.ResultsDocument &&
                $vars.extractInvoiceFieldsMock.output.ExtractionResult.ResultsDocument.Fields)
  ? $vars.extractInvoiceFieldsMock.output.ExtractionResult.ResultsDocument.Fields
  : [];

function getField(name) {
  const f = fields.find(f => f.FieldName === name);
  return f && f.Values && f.Values.length > 0 ? f.Values[0] : null;
}

const lineItemsRaw = ($vars.extractInvoiceFieldsMock.output &&
                      $vars.extractInvoiceFieldsMock.output.ExtractionResult &&
                      $vars.extractInvoiceFieldsMock.output.ExtractionResult.ResultsDocument &&
                      $vars.extractInvoiceFieldsMock.output.ExtractionResult.ResultsDocument.Tables)
  ? $vars.extractInvoiceFieldsMock.output.ExtractionResult.ResultsDocument.Tables
  : [];

const lineItems = lineItemsRaw.map(row => ({
  description: (row.find(c => c.FieldName === 'Description') || {}).Values?.[0] || null,
  quantity:    (row.find(c => c.FieldName === 'Quantity')    || {}).Values?.[0] || null,
  unitPrice:   (row.find(c => c.FieldName === 'Unit Price')  || {}).Values?.[0] || null,
  lineTotal:   (row.find(c => c.FieldName === 'Line Total')  || {}).Values?.[0] || null
}));

return {
  invoiceNumber: getField('Invoice Number'),
  vendorName:    getField('Vendor Name'),
  invoiceDate:   getField('Invoice Date'),
  totalAmount:   getField('Total Amount'),
  lineItems:     lineItems,
  fileName:      $vars.newInvoiceInSharepoint1.output.FullName,
  fileUrl:       $vars.newInvoiceInSharepoint1.output.URL
};
""".strip()

ERROR_SCRIPT = r"""
return {
  error: true,
  message: ($vars.extractInvoiceFieldsMock.error && $vars.extractInvoiceFieldsMock.error.message)
    ? $vars.extractInvoiceFieldsMock.error.message
    : 'Extraction failed',
  detail: ($vars.extractInvoiceFieldsMock.error && $vars.extractInvoiceFieldsMock.error.detail)
    ? $vars.extractInvoiceFieldsMock.error.detail
    : null,
  fileName: $vars.newInvoiceInSharepoint1.output.FullName
};
""".strip()

flow['nodes'] = [
  # Trigger (already present, keep as-is)
  flow['nodes'][0],

  # IxP mock placeholder
  {
    "id": "extractInvoiceFieldsMock",
    "type": "core.logic.mock",
    "typeVersion": "1.0",
    "display": { "label": "Extract Invoice Fields (mock — IxP model not yet deployed)" },
    "inputs": {},
    "outputs": {
      "output": {
        "type": "object",
        "description": "Mock output value",
        "source": "null",
        "var": "output"
      }
    }
  },

  # Script: format results
  {
    "id": "formatResults",
    "type": "core.action.script",
    "typeVersion": "1.0",
    "display": { "label": "Format Extracted Fields" },
    "inputs": {
      "script": EXTRACT_SCRIPT,
      "errorHandlingEnabled": True
    },
    "outputs": {
      "output": {
        "type": "object",
        "description": "The return value of the script",
        "source": "=result.response",
        "var": "output"
      },
      "error": {
        "type": "object",
        "description": "Error information if the node fails",
        "source": "=Error",
        "var": "error"
      }
    }
  },

  # Script: handle extraction errors
  {
    "id": "errorHandler",
    "type": "core.action.script",
    "typeVersion": "1.0",
    "display": { "label": "Handle Extraction Error" },
    "inputs": {
      "script": ERROR_SCRIPT
    },
    "outputs": {
      "output": {
        "type": "object",
        "description": "The return value of the script",
        "source": "=result.response",
        "var": "output"
      },
      "error": {
        "type": "object",
        "description": "Error information if the node fails",
        "source": "=Error",
        "var": "error"
      }
    }
  },

  # End: success
  {
    "id": "doneSuccess",
    "type": "core.control.end",
    "typeVersion": "1.0",
    "display": { "label": "Done" },
    "inputs": {},
    "outputs": {
      "extractedInvoice": {
        "source": "=js:$vars.formatResults.output"
      }
    }
  },

  # End: error
  {
    "id": "doneError",
    "type": "core.control.end",
    "typeVersion": "1.0",
    "display": { "label": "Done (Error)" },
    "inputs": {},
    "outputs": {
      "extractedInvoice": {
        "source": "=js:$vars.errorHandler.output"
      }
    }
  }
]

# ── Edges ──────────────────────────────────────────────────────────────────────
flow['edges'] = [
  # trigger → extract mock
  {
    "id": "edge_newInvoiceInSharepoint1_output_extractInvoiceFieldsMock_input",
    "sourceNodeId": "newInvoiceInSharepoint1",
    "sourcePort": "output",
    "targetNodeId": "extractInvoiceFieldsMock",
    "targetPort": "input"
  },
  # mock → format results (success path, mock only has output)
  {
    "id": "edge_extractInvoiceFieldsMock_output_formatResults_input",
    "sourceNodeId": "extractInvoiceFieldsMock",
    "sourcePort": "output",
    "targetNodeId": "formatResults",
    "targetPort": "input"
  },
  # format results success → done
  {
    "id": "edge_formatResults_success_doneSuccess_input",
    "sourceNodeId": "formatResults",
    "sourcePort": "success",
    "targetNodeId": "doneSuccess",
    "targetPort": "input"
  },
  # format results error → error handler
  {
    "id": "edge_formatResults_error_errorHandler_input",
    "sourceNodeId": "formatResults",
    "sourcePort": "error",
    "targetNodeId": "errorHandler",
    "targetPort": "input"
  },
  # error handler → done error
  {
    "id": "edge_errorHandler_output_doneError_input",
    "sourceNodeId": "errorHandler",
    "sourcePort": "output",
    "targetNodeId": "doneError",
    "targetPort": "input"
  }
]

# ── Definitions ────────────────────────────────────────────────────────────────
# Keep trigger definition; add script, end, mock
existing_types = {d['nodeType'] for d in flow['definitions']}

if script_def['nodeType'] not in existing_types:
    flow['definitions'].append(script_def)
if end_def['nodeType'] not in existing_types:
    flow['definitions'].append(end_def)
if mock_def['nodeType'] not in existing_types:
    flow['definitions'].append(mock_def)

# ── Variables ──────────────────────────────────────────────────────────────────
flow['variables'] = {
  "globals": [
    {
      "id": "extractedInvoice",
      "direction": "out",
      "type": "object",
      "description": "Extracted invoice fields: invoiceNumber, vendorName, invoiceDate, totalAmount, lineItems"
    }
  ],
  "nodes": [
    # trigger outputs
    {"id": "newInvoiceInSharepoint1.output", "type": "object",
     "description": "SharePoint file event payload",
     "binding": {"nodeId": "newInvoiceInSharepoint1", "outputId": "output"}},
    # mock outputs
    {"id": "extractInvoiceFieldsMock.output", "type": "object",
     "description": "IxP extraction result (mock)",
     "binding": {"nodeId": "extractInvoiceFieldsMock", "outputId": "output"}},
    # script: formatResults
    {"id": "formatResults.output", "type": "object",
     "description": "Formatted invoice fields",
     "binding": {"nodeId": "formatResults", "outputId": "output"}},
    {"id": "formatResults.error", "type": "object",
     "description": "Error if formatting fails",
     "binding": {"nodeId": "formatResults", "outputId": "error"}},
    # script: errorHandler
    {"id": "errorHandler.output", "type": "object",
     "description": "Error summary",
     "binding": {"nodeId": "errorHandler", "outputId": "output"}},
  ]
}

# ── Layout ─────────────────────────────────────────────────────────────────────
flow['layout'] = {
  "nodes": {
    "newInvoiceInSharepoint1":   {"position": {"x": 200, "y": 144}, "size": {"width": 96, "height": 96}, "collapsed": False},
    "extractInvoiceFieldsMock":  {"position": {"x": 400, "y": 144}, "size": {"width": 96, "height": 96}, "collapsed": False},
    "formatResults":             {"position": {"x": 600, "y": 144}, "size": {"width": 96, "height": 96}, "collapsed": False},
    "errorHandler":              {"position": {"x": 600, "y": 300}, "size": {"width": 96, "height": 96}, "collapsed": False},
    "doneSuccess":               {"position": {"x": 800, "y": 144}, "size": {"width": 96, "height": 96}, "collapsed": False},
    "doneError":                 {"position": {"x": 800, "y": 300}, "size": {"width": 96, "height": 96}, "collapsed": False}
  }
}

json.dump(flow, open('VendorInvoiceProcessing.flow', 'w'), indent=2)
print("Flow written successfully")
print("Nodes:", [n['id'] for n in flow['nodes']])
print("Edges:", len(flow['edges']))
print("Definitions:", [d['nodeType'] for d in flow['definitions']])
PY

